{
  "titre": "Mitose et méiose : distinguer les processus",
  "objectifGeneral": "Distinguer les mécanismes et les enjeux de la mitose et de la méiose",
  "notionsPivots": [
    "la division cellulaire",
    "le cycle cellulaire",
    "les chromosomes homologues",
    "la réplication de l'ADN",
    "la mitose",
    "la méiose",
    "les cellules filles",
    "les gamètes",
    "la diversité génétique",
    "les crossing-over"
  ],
  "etapes": [
    {
      "titre": "Diagnostic initial",
      "objectif": "Identifier ses connaissances préalables sur la division cellulaire",
      "cartes": [
        {
          "titre": "Quiz de positionnement",
          "objectif": "Repérer les idées reçues sur la mitose et la méiose",
          "module": "QuizSetVF",
          "palier": "decouverte",
          "duree": 15,
          "consigne": "Répondez à 5 affirmations sur la mitose et la méiose en cochant vrai ou faux. L'enseignant relèvera les réponses pour adapter la suite du parcours."
        }
      ]
    },
    {
      "titre": "Découverte des processus",
      "objectif": "Découvrir les étapes clés de la mitose et de la méiose",
      "cartes": [
        {
          "titre": "Frise chronologique des phases",
          "objectif": "Ordonner les phases de la mitose et de la méiose",
          "module": "SortParagraphs",
          "palier": "decouverte",
          "duree": 20,
          "consigne": "Sur papier, notez les phases de la mitose et de la méiose dans l'ordre chronologique. Comparez ensuite avec la frise projetée par l'enseignant et corrigez vos réponses."
        },
        {
          "titre": "Lexique des termes clés",
          "objectif": "S'approprier le vocabulaire spécifique",
          "module": "Glossary",
          "palier": "decouverte",
          "duree": 10,
          "consigne": "Consultez le glossaire en ligne pour comprendre les définitions des termes : cycle cellulaire, chromosomes homologues, crossing-over, cellules filles, gamètes. Notez les termes inconnus pour en discuter en groupe."
        }
      ]
    },
    {
      "titre": "Comparaison des mécanismes",
      "objectif": "Analyser les différences entre mitose et méiose",
      "cartes": [
        {
          "titre": "Tableau comparatif",
          "objectif": "Compléter un tableau comparant mitose et méiose",
          "module": "DragAndDrop",
          "palier": "entrainement",
          "duree": 25,
          "consigne": "À partir des informations du cours, glissez les étiquettes (nombre de divisions, nombre de cellules filles, type de cellules produites, etc.) dans les bonnes colonnes du tableau. L'enseignant validera collectivement."
        },
        {
          "titre": "Quiz d'application",
          "objectif": "Vérifier la compréhension des différences",
          "module": "QuizSetQCM",
          "palier": "entrainement",
          "duree": 15,
          "consigne": "Répondez à 6 questions à choix multiples sur les différences entre mitose et méiose. La correction sera faite en classe."
        }
      ]
    },
    {
      "titre": "Application et transfert",
      "objectif": "Appliquer les connaissances à des cas concrets",
      "cartes": [
        {
          "titre": "Étude de cas",
          "objectif": "Résoudre un problème biologique lié à la division cellulaire",
          "module": "Essay",
          "palier": "transfert",
          "duree": 30,
          "consigne": "En binôme, rédigez un paragraphe expliquant pourquoi la méiose est essentielle à la reproduction sexuée. Utilisez au moins 3 termes du glossaire. L'enseignant sélectionnera des productions pour une mise en commun."
        },
        {
          "titre": "Synthèse collective",
          "objectif": "Construire une synthèse partagée",
          "module": "Summary",
          "palier": "transfert",
          "duree": 20,
          "consigne": "À partir des productions des binômes, choisissez collectivement les affirmations correctes pour résumer les différences entre mitose et méiose. L'enseignant affichera la synthèse finale."
        }
      ]
    }
  ]
}
